  palette(fields,"Accent",clip.designAccent,color->{clip.designAccent=color;refresh.run();});palette(fields,"Background",clip.textBackground,color->{clip.textBackground=color;refresh.run();});palette(fields,"Text",clip.textColor,color->{clip.textColor=color;refresh.run();});fields.addView(label("Duration",13));TextView timing=label(String.format(java.util.Locale.US,"%.1f seconds",duration[0]/1000.0),13);fields.addView(timing);SeekBar length=new SeekBar(activity);length.setMax(270);length.setProgress((int)(duration[0]/100-30));length.setContentDescription("Design duration, 3 to 30 seconds");length.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean user){if(!user)return;duration[0]=(p+30)*100;clip.duration=clip.end=duration[0];EditorTitlePresets.animate(clip,duration[0],motion[0]);timing.setText(String.format(java.util.Locale.US,"%.1f seconds",duration[0]/1000.0));refresh.run();}});fields.addView(length);
