 private void amount(LinearLayout parent,String name,double current,java.util.function.DoubleConsumer change){TextView value=label(name+" · "+Math.round(current*100)+"%",13);parent.addView(value);SeekBar slider=new SeekBar(activity);slider.setMax(100);slider.setProgress((int)Math.round(current*100));slider.setContentDescription(name);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean user){if(user){value.setText(name+" · "+p+"%");change.accept(p/100.0);}}});parent.addView(slider);}
 private void field(LinearLayout parent,String title,String value,int limit,java.util.function.Consumer<String> change){parent.addView(label(title,13));EditText input=new EditText(activity);input.setTextColor(-1);input.setText(value);input.setMaxLines(4);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(limit)});input.setContentDescription(title);input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){change.accept(s.toString());}public void afterTextChanged(Editable e){}});parent.addView(input);}
 private void palette(LinearLayout parent,String title,int selected,java.util.function.IntConsumer change){parent.addView(label(title,13));LinearLayout row=new LinearLayout(activity);for(int color:new int[]{0xffffc857,0xff66d4e2,0xff8fafff,0xff7ee2bc,0xffff8b79,0xffc5a4ff,0xfff6f1e8,0xff121e2b}){Button b=button("",()->change.accept(color));b.setContentDescription(title+" "+Integer.toHexString(color));b.setMinWidth(0);b.setMinimumWidth(0);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(color));row.addView(b,new LinearLayout.LayoutParams(0,dp(38),1));}parent.addView(row);}
 private final class Preview extends View {android.media.MediaPlayer soundPlayer;void stopSound(){if(soundPlayer!=null){soundPlayer.release();soundPlayer=null;}}void playSound(){stopSound();began=SystemClock.uptimeMillis();if(!EditorTitleSounds.active(clip)){invalidate();return;}try{android.media.MediaPlayer player=new android.media.MediaPlayer();soundPlayer=player;player.setDataSource(EditorTitleSounds.file(clip).getAbsolutePath());player.setVolume((float)clip.titleSoundVolume,(float)clip.titleSoundVolume);player.setOnPreparedListener(p->{if(soundPlayer==p&&!disposed){began=SystemClock.uptimeMillis();p.start();invalidate();}});player.setOnCompletionListener(p->stopSound());player.setOnErrorListener((p,w,e)->{stopSound();return true;});player.prepareAsync();}catch(Exception e){stopSound();Toast.makeText(activity,"Could not preview sound",Toast.LENGTH_SHORT).show();}}final EditorProject.Clip clip;Bitmap bitmap;EditorTitleAnimation titleAnimation;long began=SystemClock.uptimeMillis();boolean disposed;final Paint paint=new Paint(3);Preview(EditorProject.Clip clip){super(activity);this.clip=clip;refresh();}void refresh(){stopSound();began=SystemClock.uptimeMillis()-600;if(titleAnimation!=null){titleAnimation.release();titleAnimation=null;}if(bitmap!=null)bitmap.recycle();int w=640,h=Math.max(180,Math.min(1138,Math.round(w*height/(float)Math.max(1,width))));bitmap=EditorText.bitmap(clip,w,h);invalidate();}void dispose(){disposed=true;stopSound();if(titleAnimation!=null){titleAnimation.release();titleAnimation=null;}if(bitmap!=null){bitmap.recycle();bitmap=null;}}@Override protected void onDraw(Canvas c){if(disposed||bitmap==null)return;c.drawColor(0xff344152);int w=640,h=Math.max(180,Math.min(1138,Math.round(w*height/(float)Math.max(1,width))));float scale=Math.min(getWidth()/(float)w,getHeight()/(float)h);long local=(SystemClock.uptimeMillis()-began)%Math.max(1000,clip.duration+800);EditorMotion.Key k=EditorMotion.sample(clip,Math.min(local,clip.duration),true);c.save();c.translate(getWidth()/2f,getHeight()/2f);c.scale(scale,scale);c.translate((float)k.x*w/2,(float)-k.y*h/2);c.scale((float)k.scale,(float)k.scale);paint.setAlpha((int)(255*k.alpha));Bitmap shown=bitmap;if(clip.titleDesign>0&&clip.titleMotion>0){if(titleAnimation==null)titleAnimation=new EditorTitleAnimation(clip,w,h);shown=titleAnimation.frame(local,clip.duration);}c.drawBitmap(shown,-shown.getWidth()/2f,-shown.getHeight()/2f,paint);c.restore();if(isShown()&&!disposed)postInvalidateDelayed(40);}}
